// Fires a Death Nova missile ring from a Shadow Warrior/Master minion when bShouldTrigger != 0. Selects the missile skill based on the owner's ShadowWarrior skill level (clamped to SKILL_Kick..SKILL_PoisonJavelin), then overrides to SKILL_Kick if the unit's life percentage exceeds 10%. Calls SKILLS_CreateMissileRing with missile id 0x5A at the calculated velocity.
void __fastcall MONSTER_ShadowDeathNova(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, int32_t bShouldTrigger) {
    int nSkillLvl;
    int32_t nLifePct;
    eD2Skills eSkill;
    if (!bShouldTrigger) {
      return;
    }

    D2UnitStrc* pOwner;
    pOwner = Ai::AiGeneral::GetOwnerUnit(pUnit);
    if (pOwner) {
      D2SkillStrc* pSkill;
      pSkill = D2Common::Skills::SKILLS_GetSkillByEnum(pOwner, SKILL_ShadowWarrior);
      if (pSkill) {
        nSkillLvl = D2Common::Skills::GetSkillLevel(pOwner, pSkill, 1);
        eSkill = nSkillLvl / 2 + SKILL_Kick;
        if ((int)eSkill > 1) {
          if ((int)eSkill >= 0xf) {
            eSkill = SKILL_PoisonJavelin;
          }

          goto fire_death_nova;
        }
      }
    }

    eSkill = SKILL_Kick;
    fire_death_nova:
    nLifePct = D2Common::Units::GetCurrentLifePercentage(pUnit);
    if (nLifePct > 10) {
      eSkill = SKILL_Kick;
    }

    nLifePct = D2Common::DATATBLS::MissileTbls::MISSILETBLS_CalculateVelocity(0x5a, 0);
    SKILLS::SkillsServer::SKILLS_CreateMissileRing(pGame, pUnit, pUnit, MISSILE_Nova, 0, eSkill, nLifePct);
}

// Server-side: emits the radial lightning-bolt nova fired by a lightning-enchanted unique monster (e.g. on death/trigger). When bShouldTrigger is set and at least 10 game frames have passed since the last burst (stored in the monster's data field), sets the monster's lightning-enchant flag bit, records the current game frame, computes skill level = unit level/2 (min 1), then builds a D2SkillArgStrc at the unit's position and spawns MISSILE_Lightunique charged bolts using SKILL_InitChargedBoltPath. Offsets are taken from the gnElementalDamageScale_LightningUnique / gnEnchantmentApplyScale_Lightning tables (4 directions x 2 bolts each). If <10 frames elapsed it instead clears the enchant flag bit and returns. No return value.
void __fastcall MONSTER_LightningUniqueDeathBolts(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, int32_t bShouldTrigger) {
    // Static local variables (originally global data)
    static int gaMissileOffsets_LightningUniqueX[4] = { 0x0, 0x1, 0x0, -0x1 }; D2_STATIC_GUARD(gaMissileOffsets_LightningUniqueX, "D2Game::Monsters::MONSTER_LightningUniqueDeathBolts::gaMissileOffsets_LightningUniqueX");

    int nSkillLevel;
    D2SkillArgStrc sSkillArg;
    int32_t nDirLoopOffset;
    int nSpawnOriginY;
    eD2UnitType eUnitType;
    int nDirY;
    uint16_t* pMonType;
    if (!bShouldTrigger) {
      return;
    }
    if (!pUnit || pUnit->eUnitType != UNIT_MONSTER || !pUnit->pUnitData.pUnitDataMonster) {
      nSkillLevel = 0;
    } else {
      nSkillLevel = pUnit->pUnitData.pUnitDataMonster->nDurielUnk;
    }

    nSkillLevel = pGame->dwGameFrame - nSkillLevel;
    if (nSkillLevel < 0) {
      nSkillLevel = -nSkillLevel;
    }
    if (nSkillLevel < 10) {
      if (pUnit && pUnit->eUnitType == UNIT_MONSTER && pUnit->pUnitData.pUnitDataMonster) {
        pMonType = &pUnit->pUnitData.pUnitDataMonster->eMonsterType;
        *pMonType &= 0xfeff;
        return;
      }
    } else {
      int nMissileSpawnIdx;
      if (pUnit && pUnit->eUnitType == UNIT_MONSTER) {
        if (pUnit->pUnitData.pUnitDataPlayer) {
          pUnit->pUnitData.pUnitDataPlayer->pQuestRecord[2] = (D2BitBufferStrc*)pGame->dwGameFrame;
        }
        if (pUnit->eUnitType == UNIT_MONSTER && pUnit->pUnitData.pUnitDataMonster) {
          pMonType = &pUnit->pUnitData.pUnitDataMonster->eMonsterType;
          *pMonType |= 0x100;
        }
      }

      nSkillLevel = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_level, 0);
      nSkillLevel /= 2;
      if (nSkillLevel < 1) {
        nSkillLevel = 1;
      }

      memset(&sSkillArg, 0, 0x5c);
      eUnitType = pUnit->eUnitType;
      sSkillArg.nFlags = 0x21;
      sSkillArg.pOwner = pUnit;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        sSkillArg.nX = pUnit->pPath.pStaticPath->nPosX;
      } else if (pUnit->pPath.pDynamicPath) {
        sSkillArg.nX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
      } else {
        sSkillArg.nX = 0;
      }

      eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        sSkillArg.nY = pUnit->pPath.pStaticPath->nPosY;
      } else if (pUnit->pPath.pDynamicPath) {
        sSkillArg.nY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
      } else {
        sSkillArg.nY = 0;
      }

      eUnitType = pUnit->eUnitType;
      sSkillArg.nSkillLevel = nSkillLevel;
      sSkillArg.nMissileTxtNo = MISSILE_Lightunique;
      sSkillArg.fpFunction = SKILLS::SkillSor::SKILL_InitChargedBoltPath;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        bShouldTrigger = pUnit->pPath.pStaticPath->nPosX;
      } else if (pUnit->pPath.pDynamicPath) {
        bShouldTrigger = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
      } else {
        bShouldTrigger = 0;
      }

      eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        nSpawnOriginY = pUnit->pPath.pStaticPath->nPosY;
        nDirLoopOffset = 0;
      } else if (pUnit->pPath.pDynamicPath) {
        nSpawnOriginY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
        nDirLoopOffset = 0;
      } else {
        nSpawnOriginY = 0;
        nDirLoopOffset = 0;
      }

      do {
        nSkillLevel = gaMissileOffsets_LightningUniqueX[nDirLoopOffset];
        nDirY = gaMissileOffsets_LightningUniqueY[nDirLoopOffset];
        nMissileSpawnIdx = 0;
        do {
          sSkillArg.nFunctionParam = nMissileSpawnIdx;
          sSkillArg.nUnitX = nSkillLevel + bShouldTrigger;
          sSkillArg.nUnitY = nDirY + nSpawnOriginY;
          MISSILES::Missiles::CreatingMissile(pGame, &sSkillArg);
          nMissileSpawnIdx++;
        } while (nMissileSpawnIdx < 2);

        nDirLoopOffset++;
      } while (nDirLoopOffset < 4);
    }
}

void __fastcall MONSTER_LightningDeathIfNotRunning(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, int32_t bShouldTrigger) {
    if (!(bShouldTrigger && (!pUnit || pUnit->eAnimMode.ePlayerMode != eD2PlayerAnimMode_ns::Run))) {
      return;
    }

    MONSTER_LightningUniqueDeathBolts(pGame, pUnit, dwUnused1, bShouldTrigger);
}

void __fastcall MONSTER_DeathMissileRing(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, int32_t bShouldTrigger) {
    if (!bShouldTrigger) {
      return;
    }

    int32_t nLevel = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_level, 0);
    eD2Skills eSkill = nLevel / 2;
    if ((int)eSkill <= 1) {
      eSkill = SKILL_Kick;
    }

    int32_t nMissileVelocity = D2Common::DATATBLS::MissileTbls::MISSILETBLS_CalculateVelocity(0x77, 0);
    SKILLS::SkillsServer::SKILLS_CreateMissileRing(pGame, pUnit, pUnit, MISSILE_Coldunique, 0, eSkill, nMissileVelocity);
}

