void __fastcall MONSTER_KillWithMinions(D2UnitStrc * pUnit, ::SGAMEDATA * pGame, uint32_t dwParam) {
    D2MonsterKillStrc sKillStrc;
    Ai::AiGeneral::FreeAiOfMinions(pUnit);
    Ai::AiGeneral::AssignMinionOwner(pGame, pUnit, -1, UNIT_MONSTER, 0, 0);
    if (!(pUnit && pUnit->eAnimMode.ePlayerMode != Death)) {
      return;
    }

    Monster::MonsterMode::SetCurrentSkill(pUnit, Death, &sKillStrc);
    Monster::MonsterMode::MONSTERAI_ExecuteLifecycleTransition(pGame, &sKillStrc, 1);
}

void __fastcall MONSTER_OnDeathKillOwnerAndMinions(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, uint32_t dwUnused2) {
    D2MonsterKillStrc sOwnerKillStrc;
    if (!(!pUnit || pUnit->eAnimMode.ePlayerMode == Death)) {
      return;
    }

    D2UnitStrc* pUnit_00 = Ai::AiGeneral::GetOwnerUnit(pUnit);
    if (!pUnit_00) {
      return;
    }

    Ai::AiGeneral::CallForEachMinion(pUnit, pGame, nullptr, (pfnMinionForEachCallback)MONSTER_KillWithMinions);
    Ai::AiGeneral::AssignMinionOwner(pGame, pUnit_00, -1, UNIT_MONSTER, 0, 0);
    if (!(pUnit_00 != pUnit && pUnit_00->eUnitType == UNIT_MONSTER)) {
      return;
    }

    Monster::MonsterMode::SetCurrentSkill(pUnit_00, Death, &sOwnerKillStrc);
    Monster::MonsterMode::MONSTERAI_ExecuteLifecycleTransition(pGame, &sOwnerKillStrc, 1);
}

void __fastcall UMOD_AddBaseDamageBonus(uint32_t dwUnused1, D2UnitStrc * pUnit, uint32_t dwUnused2, uint32_t dwUnused3) {
    int nMinDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_mindamage, 0);
    int nMaxDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_maxdamage, 0);
    if (!(nMaxDmg > 0 && (!pUnit || pUnit->nClassId != 0x10f))) {
      return;
    }

    int nSecondaryDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_secondary_mindamage, 0);
    nSecondaryDmg = nMinDmg - 1 + nSecondaryDmg;
    nMinDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_secondary_maxdamage, 0);
    nMinDmg = nMaxDmg - 1 + nMinDmg;
    if (nSecondaryDmg < 0) {
      nSecondaryDmg = 0;
    }
    if (nMinDmg < 0) {
      nMinDmg = 0;
    }

    D2StatListExStrc* pStatsEx = D2Common::Stats::StatsEx::GetStatsByFlags(pUnit, 1);
    D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pStatsEx, UNITSTAT_mindamage, nSecondaryDmg, 0);
    D2Common::Stats::StatsEx::D2AddStatToStatsListEx(pStatsEx, UNITSTAT_maxdamage, nMinDmg, 0);
}

void __fastcall MONSTER_ScaleMissileDamageByOwner(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, uint32_t dwUnused2) {
    if (!(pUnit && pUnit->eUnitType == UNIT_MISSILE)) {
      return;
    }

    int nMinDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_mindamage, 0);
    int nMaxDmg = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_maxdamage, 0);
    if (nMaxDmg <= 0) {
      return;
    }

    D2UnitStrc* pUnit_00 = UNIT::SUnit::GetOwnerUnit(pGame, pUnit);
    if (!(pUnit_00 && pUnit_00->nClassId == 0x10f)) {
      return;
    }

    int nSecondaryScale = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_secondary_mindamage, 0);
    nMinDmg = nMinDmg - 0x100 + nSecondaryScale * 0x100;
    nSecondaryScale = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit_00, UNITSTAT_secondary_maxdamage, 0);
    nMaxDmg = nMaxDmg - 0x100 + nSecondaryScale * 0x100;
    if (nMinDmg < 0) {
      nMinDmg = 0;
    }
    if (nMaxDmg < 0) {
      nMaxDmg = 0;
    }

    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_mindamage, nMinDmg, 0);
    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_maxdamage, nMaxDmg, 0);
}

// Spawns the Burning Dead Archer / Afflicted bug-lightning death-bolt salvo on unit death. Fires 4 directional pairs (8 total) of MISSILE_Buglightning using offsets from gaMissileOffsets_BugLightningX/Y, with SKILL_InitChargedBoltPath as the init callback. Level is taken from UNITSTAT_level; dwUnused1/dwUnused2 are ignored (death-event signature padding).
void __fastcall MONSTER_BugLightningDeathBolts(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, uint32_t dwUnused2) {
    // Static local variables (originally global data)
    static int gaMissileOffsets_BugLightningY[4] = { -0x1, 0x0, 0x1, 0x0 }; D2_STATIC_GUARD(gaMissileOffsets_BugLightningY, "D2Game::Monsters::MONSTER_BugLightningDeathBolts::gaMissileOffsets_BugLightningY");
    static int gaMissileOffsets_BugLightningX[4] = { 0x0, 0x1, 0x0, -0x1 }; D2_STATIC_GUARD(gaMissileOffsets_BugLightningX, "D2Game::Monsters::MONSTER_BugLightningDeathBolts::gaMissileOffsets_BugLightningX");

    int nPosX;
    int nPosY;
    D2SkillArgStrc sSkillArg;
    int nDirX;
    int nDirY;
    memset(&sSkillArg, 0, 0x5c);
    eD2UnitType eUnitType = pUnit->eUnitType;
    sSkillArg.nFlags = 0x21;
    sSkillArg.pOwner = pUnit;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      sSkillArg.nX = pUnit->pPath.pStaticPath->nPosX;
    } else if (pUnit->pPath.pDynamicPath) {
      sSkillArg.nX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
    } else {
      sSkillArg.nX = 0;
    }

    eUnitType = pUnit->eUnitType;
    if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
      sSkillArg.nY = pUnit->pPath.pStaticPath->nPosY;
    } else if (pUnit->pPath.pDynamicPath) {
      sSkillArg.nY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
    } else {
      sSkillArg.nY = 0;
    }

    sSkillArg.nSkillLevel = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_level, 0);
    sSkillArg.nMissileTxtNo = MISSILE_Buglightning;
    sSkillArg.fpFunction = SKILLS::SkillSor::SKILL_InitChargedBoltPath;
    int nDirLoopIdx = 0;
    do {
      int nMissileSpawnIdx;
      eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        nPosX = pUnit->pPath.pStaticPath->nPosX;
      } else if (pUnit->pPath.pDynamicPath) {
        nPosX = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
      } else {
        nPosX = 0;
      }

      eUnitType = pUnit->eUnitType;
      if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
        nPosY = pUnit->pPath.pStaticPath->nPosY;
      } else if (pUnit->pPath.pDynamicPath) {
        nPosY = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
      } else {
        nPosY = 0;
      }

      nDirX = gaMissileOffsets_BugLightningX[nDirLoopIdx];
      nDirY = gaMissileOffsets_BugLightningY[nDirLoopIdx];
      nMissileSpawnIdx = 0;
      do {
        sSkillArg.nFunctionParam = nMissileSpawnIdx;
        sSkillArg.nUnitX = nDirX + nPosX;
        sSkillArg.nUnitY = nDirY + nPosY;
        MISSILES::Missiles::CreatingMissile(pGame, &sSkillArg);
        nMissileSpawnIdx++;
      } while (nMissileSpawnIdx < 2);

      nDirLoopIdx++;
    } while (nDirLoopIdx < 4);
}

void __fastcall UMOD_SetRandomElementalDamage(::SGAMEDATA * pGame, D2UnitStrc * pUnit, uint32_t dwUnused1, int32_t bShouldTrigger) {
    // Static local variables (originally global data)
    static int gaMissileOffsets_ColdMinion[15] = {
    0x30,
    0x31,
    -0x1,
    0x32,
    0x33,
    -0x1,
    0x34,
    0x35,
    -0x1,
    0x36,
    0x37,
    0x38,
    0x39,
    0x3a,
    0x3b
}; D2_STATIC_GUARD(gaMissileOffsets_ColdMinion, "D2Game::Monsters::UMOD_SetRandomElementalDamage::gaMissileOffsets_ColdMinion");

    if (!bShouldTrigger) {
      return;
    }

    D2SeedStrc sSeedAdv = D2_SEED_NEXT(pUnit->sSeed);
    pUnit->sSeed = sSeedAdv;
    int nElemIdx = sSeedAdv.nSeedLow % 5;
    MONSTER_SetElementalDamageFromLevel(pUnit, gaMissileOffsets_ColdMinion[nElemIdx * 3], gaMissileOffsets_ColdMinion[nElemIdx * 3 + 1], gaMissileOffsets_ColdMinion[nElemIdx * 3 + 2], pGame);
}

